import{_ as a,o as n,c as t,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"From Intention to Execution: Probing the Generalization Boundaries of Vision-Language-Action Models","description":"","frontmatter":{"title":"From Intention to Execution: Probing the Generalization Boundaries of Vision-Language-Action Models","arxiv":"2506.09930","date":"2025-06-11","authors":"Irving Fang, Juexiao Zhang, Shengbang Tong, Chen Feng","categories":"cs.RO, cs.CV","topics":"具身智能, VLA 评测, 泛化能力","outline":[2,2]},"headers":[],"relativePath":"papers/2506.09930.md","filePath":"papers/2506.09930.md","lastUpdated":null}'),p={name:"papers/2506.09930.md"};function l(i,s,r,c,m,o){return n(),t("div",null,[...s[0]||(s[0]=[e('<h1 id="from-intention-to-execution-probing-the-generalization-boundaries-of-vision-language-action-models" tabindex="-1">From Intention to Execution: Probing the Generalization Boundaries of Vision-Language-Action Models <a class="header-anchor" href="#from-intention-to-execution-probing-the-generalization-boundaries-of-vision-language-action-models" aria-label="Permalink to &quot;From Intention to Execution: Probing the Generalization Boundaries of Vision-Language-Action Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2506.09930" target="_blank" rel="noreferrer">2506.09930</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-06-11</td></tr><tr><td><strong>作者</strong></td><td>Irving Fang, Juexiao Zhang, Shengbang Tong, Chen Feng</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>造 50 个仿真任务，把 VLA 的「跑对了物体」与「抓成功了」拆成两个指标分别度量，发现 VLM 带来的语义泛化几乎不转化为动作执行成功。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>VLA 相对传统模仿学习的卖点只有一条：把大型 VLM 的开放世界泛化能力接到机器人上。但这条卖点从来没被系统度量过。作者指出当前评测的两条路都走不通。仿真侧的 CALVIN、LIBERO、SimplerEnv 虽然带语言指令，但任务数量少（SimplerEnv 每个数据集只有 4 个任务），而且任务设计本来就不是为了探测泛化。真机侧的评测灵活性最高，但每个机构自建一套装置，时间与金钱成本高到无法复现。结果是：所有人都在说 VLA 泛化好，没人知道好在哪一层、哪里断掉。</p><p>这篇论文把「VLA 泛化」这个模糊说法拆成可测量的东西，做法是在同一个 SimplerEnv 底座上把任务从 4 个扩到 50 个，沿三条轴系统变化：物体多样性、语言复杂度、视觉-语言联合思考。更关键的是引入了一个新指标 Intention Correct Rate，把「模型知道该去够哪个物体」和「模型真的把物体抓起来了」分开计分。这个拆分是整篇论文的价值所在——没有它，一切失败都被记成一个笼统的低成功率，无从判断瓶颈在感知还是在控制。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>RLBench、RoboMimic、Factor World、RoboManip 这一代基准提供了标准化的操作任务，但基本不带语言指令，无法评测 VLA 的指令跟随。CALVIN 与 LIBERO 补上了语言，但作者批评它们渲染过于简单、轨迹高度单模态，从而放大 sim2real gap；更要命的是任务种类有限，泛化不是它们的设计目标。SimplerEnv 是一次实质进步：它用系统辨识 + 绿幕合成 + 统计验证，使仿真里的策略排序与真机排序对齐，因此本文选它当底座。但 SimplerEnv 只覆盖两个机器人平台、不到 10 个任务，场景里只放任务相关的源物体与目标物体，测不出杂乱与歧义。</p><p>真机评测（OpenVLA、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 等论文的做法）确实提供了物理多样性，但门槛高、不可复现。另一条相关线索来自 Factor World 等工作：光照、背景、相机位姿这些视觉因子会显著影响策略，但近年结论是「预训练视觉数据多样时，模型对光照与背景相对鲁棒，相机位姿仍是难点」。SimplerEnv 依赖绿幕合成，恰恰难以模拟光照与相机位姿变化，所以本文明确把这一轴留给前人，自己只做物体、语言、视觉杂乱三轴。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>出发点是一个已存在的经验事实：VLM 在开放词表识别和常识推理上表现很强，能从「寿司发源国春季节庆里被歌颂的花」推到樱花。既然 VLA 就是把 VLM 接上动作头，那么把 BridgeV2 里没见过的物体、把模板化指令换成绕弯的说法，模型理应仍然知道该做什么。</p><p>第二步是一个反复出现的失败观察：VLA 在演示分布内表现好，一旦换物体或换措辞成功率就掉。但成功率是一个复合量——它同时包含「找错了目标」和「找对了但没抓住」两种完全不同的失败。既然要判断 VLM 的贡献到底传导到哪一层，就必须把这两件事分开测。SimplerEnv 原生只报抓取成功与任务成功，那就再加一个更早期的观测量：夹爪是否曾进入正确源物体的一个小半径内。</p><p>第三步是控制变量的设计。若只换源物体，抓取原语本身没变，抓取成功率理论上应该稳定；如果它随目标物体变化而剧烈波动，那就说明高层感知与低层动作是纠缠的，而不是两个可独立复用的模块。这个对照几乎不花额外成本，却能直接证伪「VLA 是感知模块 + 通用抓取原语」的朴素图景。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>VLM 教会了 VLA「要去哪」，但没教会它「怎么到那」。当观测落到分布外时，策略仍然把夹爪送到正确的物体上方——意图是对的——却在最后几厘米的接触与闭合上失败。因此看总成功率会误以为模型「不理解任务」，实际上语义那一半基本没坏，坏的是从语义到精细运动的传导。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>INT-ACT 建在 SimplerEnv/ManiSkill2 之上，围绕 BridgeV2 的 WidowX 平台展开，共 50 个任务、10 个子类。以一条具体任务链为例：</p><ul><li><strong>原始任务</strong>：<code>Put carrot on plate</code>（BridgeV2 分布内）。</li><li><strong>物体轴</strong>：把目标换成 ramekin、键盘、轮子等 OOD 物体；把源物体换成可乐罐、工业工具等；或源与目标同时 OOD；再或者两个物体都见过但关系没见过（把胡萝卜放到海绵上），用来探测模型是否记住了虚假的共现相关。</li><li><strong>语言轴</strong>：Language Action（把动词换成不常见的组合式说法）、Language Negation（对无关物体加否定，如「不要动 X」）、Language Appearance（用「那个紫色的东西」代替「茄子」）。</li><li><strong>视觉-语言轴</strong>：往场景里塞与任务无关的干扰物；再塞需要常识才能消歧的干扰物，例如指令说拿橙汁盒，场景里放一个橙子；最后把常识改写与干扰物叠加，例如把胡萝卜说成「兔子最爱的蔬菜」，同时在场景里放一只玩具兔。</li></ul><p>评测协议：每个任务跑 24 个 episode（对应 ManiSkill2 预定义的全部场景与物体配置），每个配置重复 3 个随机种子，指标在 episode 与种子上平均。三个指标分别是 Intention Correct Rate（夹爪任一帧进入正确源物体的小半径内）、Grasp Success Rate（任一帧成功抓住正确源物体）、Task Success Rate。在常识+干扰的案例研究里另加一个 Wrong Object Attempt Rate，记录是否移动了非源物体。</p><p>被测模型有四族六个变体：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-finetune（从官方 checkpoint 在 BridgeV2 微调）、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-scratch（只用 PaliGemma 和 BridgeV2 从头训）、SpatialVLA（官方 BridgeV2 checkpoint）、Magma（零样本，带视觉语言协同训练）、Octo Small/Base（零样本）。另有一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-finetune+rephrase，用改写过的指令微调，专门检验「多样化措辞能否补上语言鲁棒性」。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：意图与执行之间有多大差距？</strong> 表 1 给出的平均值极不对称：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-finetune 的 intention/grasp/success 是 84.5 / 54.4 / 30.4，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-scratch 是 89.5 / 66.7 / 48.9，Magma 是 85.4 / 46.5 / 21.6。也就是说 VLM 初始化的 VLA 在几乎所有类别上 intention 都在 80–100，任务成功率却掉到 20–50。连 Octo Small 这种非 VLM 基线也有 31.5 的 intention 对应 1.6 的 success。作者据此断言：VLM 赋予的是「做什么」的可泛化概念，卡住的是把这个概念翻译成稳健低层控制。</p><p>值得指出的是这条结论并非在每个模型上都成立。SpatialVLA 在 OOD Src+Tgt 上 intention 只有 42.5，在 OOD Relation 上只有 17.7，明显不是「意图正确、执行失败」，而是意图本身就崩了。论文的概括在这一格上偏乐观。</p><p><strong>问题二：只换目标物体会不会影响抓源物体？</strong> 会。在固定源物体、只改目标物体的对照里，抓取成功率的摆动可达 40 个百分点，而抓取原语本身没有理由改变。作者以此论证端到端策略里高层感知与低层动作是脆弱耦合的。另一个有意思的观察是：从未在 BridgeV2 出现过的可乐罐，抓取成功率普遍高于常见的胡萝卜——决定执行难度的是几何形状而非 OOD 与否。</p><p><strong>问题三：语言泛化保住了吗？</strong> 没有。表 2 显示所有模型在三类语言扰动下全部退化。SpatialVLA 在 Lang. Action 上 intention 从 100 掉到 52.1；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-finetune 在 Lang. Negation 上三项分别掉 24.0 / 20.8 / 24.3。用改写指令微调的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-finetune+rephrase 确实把 Lang. Action 的 intention 恢复到 98.6（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">+</span><span class="mord">0.0</span></span></span></span>），但它的执行并未跟着恢复，而且在 Lang. Appearance 上 grasp 反而掉了 30.9——比不做改写微调时掉得更多。</p><p><strong>问题四：常识与干扰叠加会怎样？</strong> 单独加干扰物或单独换成常识描述时，模型的 intention 基本保住，Wrong Object Attempt 接近零。但当「兔子最爱的蔬菜」这句话与场景里的玩具兔同时出现时，错误物体尝试率骤升，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-finetune 尤其明显；橙汁盒 + 橙子这一组更是让所有模型集体失守。结论是语言先验会压过视觉 grounding。</p><p>一个论文自己没有强调、但表格直接给出的事实：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-scratch 在几乎每一列上都优于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-finetune（成功率 48.9 vs 30.4）。也就是说，用官方大规模机器人预训练 checkpoint 起步反而不如只拿 PaliGemma 加 BridgeV2 从头训。这与「更多机器人预训练数据总是更好」的直觉相反，论文未展开讨论。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：INT-ACT 在 SimplerEnv 上扩出 50 个任务、10 个子类，沿物体、语言、视觉-语言三轴系统探测 VLA 泛化。它引入 Intention Correct Rate，把「找对目标」与「抓成功」拆开度量。结果是所有 VLM 初始化的 VLA 都保持高意图正确率但任务成功率大幅下滑，形成 Intention-Action Gap。语言侧的泛化在端到端 VLA 训练后严重损失，用改写指令微调只能救回意图、救不回执行。当常识改写与视觉干扰叠加时，语言先验会压过视觉 grounding，导致系统性地去动错误物体。</p><p><strong>3 句话版</strong>：VLM 骨干给了 VLA 稳健的「要做什么」，但这个语义优势几乎不传导到精细运动执行。同时，端到端动作数据训练会侵蚀原 VLM 的语言泛化能力。多模态歧义（常识 + 干扰）是当前 VLA 最脆的一环。</p><p><strong>1 句话版</strong>：当前 VLA 的瓶颈不在语义理解，而在从语义到动作的那一段传导，而且这段传导会随目标物体的变化而莫名其妙地失效。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的是 Intention Correct Rate 的构造：它被定义为「夹爪在任一帧进入正确源物体的一个小半径内」。整篇论文的核心结论——语义没坏、执行坏了——完全建立在「这个几何邻近性度量能代表语义意图」之上。</p><p>这条假设在实践中很可能不成立。夹爪进入某物体邻域可以有三种来源：真的识别并锁定了它、在探索性摆动中恰好扫过、或者演示数据里的运动先验本来就把夹爪往桌面中央送。半径未在正文给出，桌面上物体又相互靠近，&quot;任一帧&quot;的宽松判据进一步放大了偶然命中的概率。论文提供的旁证是附录 B 里对预训练 PaliGemma 的 VQA 测试（说明底座 VLM 确实理解这些指令），但那测的是 VLM 而不是 VLA 的行为。缺的证据是：一个不看语言、只按视觉显著性走的盲基线在同样指标下能拿多少分。如果盲基线也能拿到 60–80 的 intention，那么「意图正确率高」就不再是 VLM 语义的证据，Intention-Action Gap 的解释就要整个改写。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要训练任何模型：</p><ul><li>取 SimplerEnv/ManiSkill2 与 INT-ACT 开源任务集，只跑「OOD Source」与「Object Distractor」两个子类，各 3–5 个任务。</li><li>实现两个盲基线：(a) 忽略语言，把夹爪直接送往画面中面积最大的可抓物体；(b) 忽略语言，在桌面工作空间内随机游走固定步数。</li><li>用论文的 Intention Correct Rate 判据给两个基线打分，同时用公开的 Octo Small 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-finetune checkpoint 复现表 1 对应格。</li><li>判据：若盲基线的 intention 显著低于 Octo Small 的 31.5，说明该指标确实携带语义信息，Intention-Action Gap 成立；若盲基线接近甚至超过 Octo，则该指标主要在测「夹爪有没有靠近桌面物体」，论文的核心叙事需要重新归因。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>论文把「抓取成功率随目标物体变化而摆动 40%」当作高层与低层纠缠的证据。一个更朴素的替代解释是：这些任务的成功判据是把源物体放到目标上，而目标物体的几何（ramekin 有凹壁、键盘是薄平面、轮子是曲面）直接改变了放置阶段的难度，也改变了接近轨迹，从而回过头影响抓取阶段的姿态。换句话说，摆动可能是任务物理难度的差异，而不是感知-动作耦合的病理。</p><p>判决实验：固定源物体与目标物体，只把目标物体的<strong>贴图</strong>换成另一件物体的外观而保持几何不变；再做一组只换几何不换贴图。若抓取成功率主要随几何变化而随贴图基本不动，则耦合论被证伪，摆动应归因于物理难度。</p><p>第二个反例针对语言结论。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-scratch（未用机器人预训练 checkpoint）在语言扰动下的退化幅度明显小于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-finetune，且绝对分更高。这提示「端到端动作训练侵蚀语言能力」的说法或许该改成「大规模跨本体机器人预训练侵蚀语言能力」。缺的对照是同一底座 PaliGemma 在三种条件下的语言扰动退化曲线：纯 VLM、只在 BridgeV2 训、先跨本体预训练再在 BridgeV2 训。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：本文测出了 gap 却无法定位它。intention 与 success 之间只有一个数字之差，看不出模型是在哪一个空间尺度上失守的。</p><p><strong>新 framing</strong>：不要把 VLA 当成「感知 + 控制」两段，而把它当成一个多分辨率的对齐问题——语义 grounding 在厘米级是对的，在毫米级是错的。相邻领域可借的工具是视觉定位与位姿估计里的<strong>误差分解</strong>方法：在 rollout 的每一帧上同时读出策略隐层对目标物体的隐式定位（用线性探针从隐层回归物体的图像坐标与深度），与真值比对，得到一条随时间与距离变化的定位误差曲线。</p><p><strong>第一个实验</strong>：在 INT-ACT 的 OOD Source 子类上，对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-scratch 的每一层训练一个冻结的线性探针，回归源物体在相机坐标系下的 3D 位置。分别在「夹爪距目标 &gt;10 cm」「2–10 cm」「&lt;2 cm」三个区间统计探针误差。若探针误差在远距离时很小、在接近时急剧变大，则 gap 的位置被定位到「近距离精细定位」，后续可以只在这一段上加监督（例如触觉或腕部高分辨率视觉），而不必重训整个 VLA。若探针误差在三个区间都很小，则定位不是瓶颈，问题出在动作解码器，结论完全不同。这个实验不需要重新训练策略，也能给出比单一成功率信息量高得多的诊断。</p>',47)])])}const d=a(p,[["render",l]]);export{g as __pageData,d as default};
